mapper.update:
UPDATE site
SET last_commit_id = #{commitId}
WHERE site_id = #{siteId}
  AND deleted = 0

UPDATE site
SET state   = 'DELETED',
    deleted = 1
WHERE site_id = #{siteId}
  AND deleted = 0
;

UPDATE site
SET state = #{state}
WHERE site_id = #{siteId}
  AND deleted = 0

UPDATE site
SET publishing_enabled = #{enabled}
WHERE site_id = #{siteId}
  AND deleted = 0

UPDATE site
SET staging_blobs_copied = #{copied}
WHERE site_id = #{siteId}
  AND deleted = 0

UPDATE site
SET publishing_status = #{publishingStatus}
WHERE site_id = #{siteId}
  AND deleted = 0

